import React from 'react'
import servicesData from "./ServicesData.js";
import classes from './Services.module.scss';

const Services = () => {
  return (
    <div className={classes.servicePage}>
      {servicesData.map((section, index) => (
        <div className={classes.serviceSection} key={index}>
          <div></div>
          <img className={classes.audioWave} src="/img/AudioWave.png" alt="Audio Wave" />
          <h1 className={classes.sectionTitle}>{section.title}</h1>

          <div className={classes.serviceItems}>
            {section.items.map((item, itemIndex) => (
              <div className={classes.serviceItem} key={itemIndex}>
                <h3 className={classes.serviceName}>{item.name}</h3>
                <p className={classes.servicePrice}>{item.price}</p>
                <p className={classes.serviceDescription}>{item.description}</p>
              </div>
            ))}
          </div>
        </div>
      ))}
    </div>);
}

export default Services
